The client
Save this as assembly_client.py in your project:
import os, asyncio
from typing import Optional
import httpx
from dotenv import load_dotenv

load_dotenv()

BASE_URL = "https://open.assembly.go.kr/portal/openapi"
UNIT_CD  = {"22": "100022", "21": "100021", "20": "100020", "19": "100019", "18": "100018"}


class AssemblyClient:
    def __init__(self):
        self.key = os.getenv("ASSEMBLY_API_KEY")
        if not self.key:
            raise ValueError("ASSEMBLY_API_KEY not set")
        self._http = httpx.AsyncClient(timeout=30)

    async def __aenter__(self): return self
    async def __aexit__(self, *_): await self._http.aclose()

    def _base(self):
        return {"KEY": self.key, "Type": "json"}

    def _parse(self, data: dict, ep: str) -&gt; list[dict]:
        """Parse 열린국회 API response. Returns [] on INFO-200 (no results)."""
        body = data.get(ep, [])
        if not body:
            return []
        code = body[0]["head"][1]["RESULT"]["CODE"]
        if code == "INFO-200":
            return []
        if code != "INFO-000":
            raise ValueError(f"API error {code}: {body[0]['head'][1]['RESULT']['MESSAGE']}")
        rows = body[1].get("row", []) if len(body) &gt; 1 else []
        return rows if isinstance(rows, list) else [rows]  # normalize single-record responses

    async def get(self, endpoint: str, **params) -&gt; list[dict]:
        merged = {**self._base(), **{k: v for k, v in params.items() if v is not None}}
        r = await self._http.get(f"{BASE_URL}/{endpoint}", params=merged)
        r.raise_for_status()
        return self._parse(r.json(), endpoint)

    # ── Convenience methods ────────────────────────────────────────────────────

    async def search_bills(self, age: str, bill_name=None, proposer=None,
                           proc_result=None, committee=None, page=1, page_size=100):
        return await self.get("nzmimeepazxkubdpn",
            AGE=age, BILL_NAME=bill_name, PROPOSER=proposer,
            PROC_RESULT=proc_result, COMMITTEE=committee,
            pIndex=page, pSize=page_size)

    async def get_members(self, age="22", name=None, party=None,
                          district=None, committee=None, page_size=300):
        return await self.get("nwvrqwxyaytdsfvhu",
            UNIT_CD=UNIT_CD.get(age, f"1000{age}"), HG_NM=name,
            POLY_NM=party, ORIG_NM=district, CMIT_NM=committee, pSize=page_size)

    async def get_votes(self, age: str, bill_name=None, page_size=100):
        return await self.get("ncocpgfiaoituanbr",
            AGE=age, BILL_NAME=bill_name, pSize=page_size)

    async def get_proposers(self, bill_id: str):
        return await self.get("BILLINFOPPSR", BILL_ID=bill_id)

API response structure
Every 열린국회정보 endpoint returns the same envelope:
{
  "nzmimeepazxkubdpn": [
    {
      "head": [
        { "list_total_count": 15234 },
        { "RESULT": { "CODE": "INFO-000", "MESSAGE": "정상" } }
      ]
    },
    {
      "row": [
        { "BILL_NO": "2200001", "BILL_NAME": "...", ... },
        ...
      ]
    }
  ]
}
Key response codes:



Code
Meaning




INFO-000
Success — row contains results


INFO-200
No results found (not an error)


ERROR-290
Invalid API key


ERROR-310
Endpoint does not exist









WarningSingle-record edge case



When a query returns exactly one result, the API returns row as a dict instead of a list. Always normalize: rows if isinstance(rows, list) else [rows].

Core functions
Save this as assembly_api.R:
library(httr2)
library(jsonlite)
library(tidyverse)
library(glue)

BASE_URL &lt;- "https://open.assembly.go.kr/portal/openapi"
UNIT_CD  &lt;- c("22"="100022","21"="100021","20"="100020","19"="100019","18"="100018")

assembly_get &lt;- function(endpoint, ...) {
  params &lt;- list(KEY = Sys.getenv("ASSEMBLY_API_KEY"), Type = "json", ...)

  resp &lt;- request(glue("{BASE_URL}/{endpoint}")) |&gt;
    req_url_query(!!!params) |&gt;
    req_error(is_error = \(r) FALSE) |&gt;
    req_perform() |&gt;
    resp_body_json()

  body  &lt;- resp[[endpoint]]
  code  &lt;- body[[1]]$head[[2]]$RESULT$CODE

  if (code == "INFO-200") return(tibble())           # empty result — not an error
  if (code != "INFO-000") stop(glue("API error {code}: {body[[1]]$head[[2]]$RESULT$MESSAGE}"))

  rows &lt;- body[[2]]$row
  if (is.null(rows)) return(tibble())

  # Normalize: single result returns a named list, not a list-of-lists
  if (!is.null(names(rows))) rows &lt;- list(rows)

  bind_rows(map(rows, as_tibble))
}

# ── Convenience wrappers ───────────────────────────────────────────────────────

search_bills &lt;- function(age, bill_name=NULL, proposer=NULL,
                         proc_result=NULL, committee=NULL,
                         page=1, page_size=100) {
  assembly_get("nzmimeepazxkubdpn",
    AGE=age, BILL_NAME=bill_name, PROPOSER=proposer,
    PROC_RESULT=proc_result, COMMITTEE=committee,
    pIndex=page, pSize=page_size)
}

get_members &lt;- function(age="22", name=NULL, party=NULL,
                        district=NULL, committee=NULL, page_size=300) {
  assembly_get("nwvrqwxyaytdsfvhu",
    UNIT_CD=UNIT_CD[[age]], HG_NM=name, POLY_NM=party,
    ORIG_NM=district, CMIT_NM=committee, pSize=page_size)
}

get_votes &lt;- function(age, bill_name=NULL, page_size=100) {
  assembly_get("ncocpgfiaoituanbr",
    AGE=age, BILL_NAME=bill_name, pSize=page_size)
}

get_proposers &lt;- function(bill_id) {
  assembly_get("BILLINFOPPSR", BILL_ID=bill_id)
}

Example 4: Committee composition and balance-of-party analysis
source("assembly_api.R")

committees &lt;- c("법제사법위원회", "국토교통위원회", "기획재정위원회",
                "과학기술정보방송통신위원회", "보건복지위원회")

committee_data &lt;- map_dfr(committees, function(cmit) {
  get_members(age = "22", committee = cmit, page_size = 100) |&gt;
    mutate(committee = cmit)
}, .id = NULL)

# Party balance per committee
party_balance &lt;- committee_data |&gt;
  count(committee, POLY_NM) |&gt;
  group_by(committee) |&gt;
  mutate(share = n / sum(n)) |&gt;
  ungroup()

party_balance |&gt;
  filter(POLY_NM %in% c("더불어민주당", "국민의힘")) |&gt;
  pivot_wider(names_from = POLY_NM, values_from = share) |&gt;
  arrange(desc(`더불어민주당`))






TipUsing with fixest and did



The get_votes() data integrates well with fixest::feols() for two-way fixed effects, and the search_bills() data (with date variables) can feed did::att_gt() for staggered DiD designs where the treatment is a policy enactment date.
